import dotenv from 'dotenv';
import path from 'path';
import { fileURLToPath } from 'url';
import { PrismaClient } from '@prisma/client';
import { PrismaPg } from '@prisma/adapter-pg';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

dotenv.config({ path: path.join(__dirname, '../../.env') });

const prismaClientSingleton = () => {
  if (process.env.NODE_ENV === 'test') return {} as PrismaClient;
  const adapter = new PrismaPg({ connectionString: process.env.DATABASE_URL! });
  return new PrismaClient({ adapter });
};

declare global {
  var prisma: undefined | ReturnType<typeof prismaClientSingleton>;
}

const prisma = globalThis.prisma ?? prismaClientSingleton();

export default prisma;

if (process.env.NODE_ENV !== 'production') globalThis.prisma = prisma;

import { Request, Response } from 'express';
import { createNonce, authenticateWallet } from '../services/auth.services.js';
import { resendEmailOtp, verifyEmailOtp } from '../services/otp.services.js';
import { sanitizeMerchant } from '../services/merchant.services.js';
import { AppError } from '../utils/errors.js';

export const createNonceController = async (req: Request, res: Response) => {
  try {
    const { address } = req.body;
    if (!address || typeof address !== 'string') {
      res.status(400).json({ error: 'address is required' });
      return;
    }
    const result = await createNonce(address);
    res.status(201).json(result);
  } catch (error) {
    res.status(500).json({ error: 'Internal Server Error' });
  }
};

export const verifySignatureController = async (req: Request, res: Response) => {
  try {
    const { address, nonce, signature } = req.body;
    if (!address || !nonce || !signature) {
      res.status(400).json({ error: 'address, nonce, and signature are required' });
      return;
    }
    if (typeof address !== 'string' || typeof nonce !== 'string' || typeof signature !== 'string') {
      res.status(400).json({ error: 'address, nonce, and signature must be strings' });
      return;
    }

    const result = await authenticateWallet(address, nonce, signature);

    if (!result.success) {
      res.status(401).json({ error: result.reason });
      return;
    }

    res.status(200).json({
      accessToken: result.accessToken,
      refreshToken: result.refreshToken,
      merchant: result.merchant,
    });
  } catch (error) {
    res.status(500).json({ error: 'Internal Server Error' });
  }
};

export const verifyEmailController = async (req: Request, res: Response): Promise<void> => {
  const merchant = req.merchant;

  if (!merchant) {
    res.status(401).json({ error: 'Unauthorized' });
    return;
  }

  const { code } = req.body;
  if (!code || typeof code !== 'string') {
    res.status(400).json({ error: 'code is required' });
    return;
  }

  try {
    const updatedMerchant = await verifyEmailOtp(merchant.id, code.trim());
    res.status(200).json(sanitizeMerchant(updatedMerchant));
  } catch (error) {
    if (error instanceof AppError) {
      res.status(error.statusCode).json({ error: error.message });
      return;
    }
    res.status(500).json({ error: 'Internal Server Error' });
  }
};

export const resendOtpController = async (req: Request, res: Response): Promise<void> => {
  const merchant = req.merchant;

  if (!merchant) {
    res.status(401).json({ error: 'Unauthorized' });
    return;
  }

  try {
    await resendEmailOtp(merchant.id);
    res.status(200).json({ message: 'Verification code sent' });
  } catch (error) {
    if (error instanceof AppError) {
      res.status(error.statusCode).json({ error: error.message });
      return;
    }
    res.status(500).json({ error: 'Internal Server Error' });
  }
};

import { Request, Response } from 'express';
import {
  createMerchant,
  getMerchant,
  listMerchants,
  registerMerchant,
  getMyProfile,
  updateMyProfile,
  generateMerchantSigningKey,
} from '../services/merchant.services.js';
import { validateRegisterMerchant, validateUpdateMerchant } from '../utils/validation.js';
import { AppError } from '../utils/errors.js';

export const createMerchantController = async (req: Request, res: Response) => {
  try {
    const merchant = await createMerchant(req.body);
    res.status(201).json(merchant);
  } catch (error) {
    res.status(500).json({ error: 'Internal Server Error' });
  }
};

export const getMerchantController = async (req: Request, res: Response) => {
  try {
    const merchant = await getMerchant(Number(req.params.id));
    res.status(200).json(merchant);
  } catch (error) {
    res.status(500).json({ error: 'Internal Server Error' });
  }
};

export const listMerchantsController = async (req: Request, res: Response) => {
  try {
    const merchants = await listMerchants(Number(req.query.limit), Number(req.query.offset));
    res.status(200).json(merchants);
  } catch (error) {
    res.status(500).json({ error: 'Internal Server Error' });
  }
};

export const registerMerchantController = async (req: Request, res: Response): Promise<void> => {
  const merchant = req.merchant;

  if (!merchant) {
    res.status(401).json({ error: 'Unauthorized' });
    return;
  }

  const errors = validateRegisterMerchant(req.body);
  if (Object.keys(errors).length > 0) {
    res.status(400).json({ error: 'Validation failed', errors });
    return;
  }

  try {
    const profile = await registerMerchant(merchant.id, req.body);
    res.status(200).json(profile);
  } catch (error) {
    if (error instanceof AppError) {
      res.status(error.statusCode).json({ error: error.message });
      return;
    }
    res.status(500).json({ error: 'Internal Server Error' });
  }
};

