import { scValToNative } from '@stellar/stellar-sdk';
import prisma from '../config/prisma.js';
import { environment } from '../config/environment.js';
import { sorobanServer } from './sorobanClient.js';
import { dispatch } from './registry.js';

let isRunning = false;
let cursor: number | undefined;

function decodeTopic(val: any): string {
  if (!val) return '';
  try {
    const native = scValToNative(val);
    if (typeof native === 'symbol') {
      return native.description ?? native.toString();
    }
    return String(native);
  } catch {
    return 'unknown_topic';
  }
}

export async function tick(): Promise<void> {
  try {
    const contractId = environment.stellar.contractId;
    if (!contractId || contractId.trim() === '') {
      throw new Error('STELLAR_CONTRACT_ID environment variable is unset or empty');
    }

    const latestLedgerResp = await sorobanServer.getLatestLedger();
    const latestLedger = latestLedgerResp.sequence;

    if (cursor === undefined) {
      const cursorRecord = await prisma.indexerCursor.findUnique({
        where: { contractId },
      });
      if (cursorRecord?.lastLedger != null) {
        cursor = cursorRecord.lastLedger;
      } else if (environment.stellar.indexerStartLedger != null) {
        cursor = environment.stellar.indexerStartLedger;
      } else {
        cursor = latestLedger;
      }
      console.log(`Indexer initialized with cursor at ledger ${cursor}`);
    }

    const currentCursor = cursor ?? latestLedger;
    cursor = currentCursor;

    if (currentCursor > latestLedger) {
      return;
    }

    const eventsResp = await sorobanServer.getEvents({
      startLedger: currentCursor,
      filters: [{ type: 'contract', contractIds: [contractId] }],
      limit: 100,
    });

    const events = eventsResp.events || [];
    const processedIds: { id: string; topic: string; ledger: number }[] = [];

    for (const event of events) {
      try {
        const existing = await prisma.indexerEvent.findUnique({
          where: { id: event.id },
        });
        if (existing) {
          continue;
        }

        const topicVal = event.topic && event.topic.length > 0 ? event.topic[0] : undefined;
        const decodedTopic = decodeTopic(topicVal);
        let decodedValue: any = null;
        try {
          decodedValue = event.value ? scValToNative(event.value) : null;
        } catch {
          decodedValue = null;
        }

        console.log(`Decoded event [${event.id}] - topic: ${decodedTopic}, value:`, decodedValue);

        await dispatch({
          id: event.id,
          topic: decodedTopic,
          ledger: event.ledger,
          txHash: event.txHash,
          data: decodedValue,
        });

        processedIds.push({
          id: event.id,
          topic: decodedTopic,
          ledger: event.ledger,
        });
      } catch (err) {
        console.error(`Error processing event ${event.id}:`, err);
      }
    }

    const nextCursor =
      events.length === 100 && events[events.length - 1]
        ? events[events.length - 1].ledger + 1
        : latestLedger + 1;

    await prisma.$transaction(async tx => {
      for (const item of processedIds) {
        await tx.indexerEvent.create({
          data: {
            id: item.id,
            topic: item.topic,
            ledger: item.ledger,
          },
        });
      }
      await tx.indexerCursor.upsert({
        where: { contractId },
        update: { lastLedger: nextCursor },
        create: { contractId, lastLedger: nextCursor },
      });
    });

    cursor = nextCursor;
  } catch (error) {
    console.error('Error in poller tick:', error);
    if (!environment.stellar.contractId || environment.stellar.contractId.trim() === '') {
      throw error;
    }
  }
}

export async function startPolling(intervalMs = 6000): Promise<void> {
  const contractId = environment.stellar.contractId;
  if (!contractId || contractId.trim() === '') {
    throw new Error('STELLAR_CONTRACT_ID environment variable is unset or empty');
  }
  if (isRunning) return;
  isRunning = true;
  console.log(`Starting Soroban indexer poller for contract ${contractId}...`);

  while (isRunning) {
    await tick();
    if (!isRunning) break;
    await new Promise(resolve => setTimeout(resolve, intervalMs));
  }
}

export function stopPolling(): void {
  isRunning = false;
}

export function getCursor(): number | undefined {
  return cursor;
}

export function setCursor(val: number | undefined): void {
  cursor = val;
}

export function resetPoller(): void {
  stopPolling();
  cursor = undefined;
}

import { DecodedEvent } from './types.js';

export type EventHandler = (event: DecodedEvent) => Promise<void> | void;

const handlers = new Map<string, EventHandler>();

export function registerEventHandler(topic: string, handler: EventHandler): void {
  handlers.set(topic, handler);
}

export async function dispatch(event: DecodedEvent): Promise<void> {
  const handler = handlers.get(event.topic);
  if (!handler) {
    console.log(`No handler registered for topic "${event.topic}", skipping.`);
    return;
  }
  await handler(event);
}

export function clearHandlers(): void {
  handlers.clear();
}

import { startPolling, stopPolling } from './poller.js';

process.on('SIGINT', () => {
  console.log('Received SIGINT, shutting down indexer...');
  stopPolling();
});

process.on('SIGTERM', () => {
  console.log('Received SIGTERM, shutting down indexer...');
  stopPolling();
});

startPolling().catch(error => {
  console.error('Fatal error starting Soroban indexer:', error);
  process.exit(1);
});

export interface DecodedEvent {
  id: string;
  topic: string;
  ledger: number;
  txHash: string;
  data: any;
}

import { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';
import prisma from '../config/prisma.js';
import { environment } from '../config/environment.js';
import { authenticateApiKey } from '../services/api-key.services.js';
import { isApiKeyToken } from '../utils/api-key.utils.js';

const extractBearerToken = (req: Request): string | null => {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return null;
  }

  const token = authHeader.slice('Bearer '.length).trim();
  return token || null;
};

const authenticateRefreshToken = async (token: string) => {
  const session = await prisma.refreshToken.findUnique({
    where: { token },
    include: { merchant: true },
  });

  if (!session || session.expiresAt.getTime() < Date.now()) {
    return null;
  }

  return session.merchant;
};

const authenticateJwt = async (token: string) => {
  try {
    const payload = jwt.verify(token, environment.jwtSecret) as { sub?: string };
    if (!payload.sub) {
      return null;
    }

    return prisma.merchant.findUnique({ where: { id: payload.sub } });
  } catch {
    return null;
  }
};

const resolveMerchantFromToken = async (token: string) => {
  if (isApiKeyToken(token)) {
    return authenticateApiKey(token);
  }

  if (token.split('.').length === 3) {
    return authenticateJwt(token);
  }

  return authenticateRefreshToken(token);
};

/**
 * Authenticates API key bearer tokens, updates lastUsedAt, and attaches the merchant.
 */
export const apiKeyAuth = async (
  req: Request,
  res: Response,
  next: NextFunction,
): Promise<void> => {
  try {
    const token = extractBearerToken(req);

    if (!token) {
      res.status(401).json({ error: 'Authentication required' });
      return;
    }

    if (!isApiKeyToken(token)) {
      res.status(401).json({ error: 'Invalid or expired token' });
      return;
    }

    const merchant = await authenticateApiKey(token);
    if (!merchant) {
      res.status(401).json({ error: 'Invalid or expired token' });
      return;
    }

    req.merchant = merchant;
    next();
  } catch {
    res.status(500).json({ error: 'Internal Server Error' });
  }
};

/**
 * Authenticates a merchant using refresh tokens or JWT access tokens only.
 * API keys are rejected to prevent key-management operations via API keys.
 */
export const authenticateSessionOnly = async (
  req: Request,
  res: Response,
  next: NextFunction,
): Promise<void> => {
  try {
    const token = extractBearerToken(req);

    if (!token) {
      res.status(401).json({ error: 'Authentication required' });
      return;
    }

    if (isApiKeyToken(token)) {
      res.status(401).json({ error: 'Invalid or expired token' });
      return;
    }

    const merchant =
      token.split('.').length === 3
        ? await authenticateJwt(token)
        : await authenticateRefreshToken(token);

    if (!merchant) {
      res.status(401).json({ error: 'Invalid or expired token' });
      return;
    }

    req.merchant = merchant;
    next();
  } catch {
    res.status(500).json({ error: 'Internal Server Error' });
  }
};

/**
 * Authenticates a merchant from a bearer token.
 *
 * Accepts JWT access tokens (signed with `JWT_SECRET`), refresh session tokens,
 * or API keys. The resolved Merchant is attached to `req.merchant` on success.
 *
 * Responds with 401 when the `Authorization: Bearer <token>` header is missing
 * or malformed (`Authentication required`), or when the token is invalid,
 * expired, or references a merchant that no longer exists
 * (`Invalid or expired token`).
 */
export const authenticateMerchant = async (
  req: Request,
  res: Response,
  next: NextFunction,
): Promise<void> => {
  try {
    const token = extractBearerToken(req);

    if (!token) {
      res.status(401).json({ error: 'Authentication required' });
      return;
    }

    const merchant = await resolveMerchantFromToken(token);
    if (!merchant) {
      res.status(401).json({ error: 'Invalid or expired token' });
      return;
    }

    req.merchant = merchant;
    next();
  } catch {
    res.status(500).json({ error: 'Internal Server Error' });
  }
};

import app from './app.js';
import { environment } from './config/environment.js';

const startServer = async () => {
  try {
    // Start Express server
    app.listen(environment.port, () => {
      console.log(`Server running on port ${environment.port} in ${environment.nodeEnv} mode`);
    });
  } catch (error) {
    console.error('Error starting server:', error);
    process.exit(1);
  }
};

startServer();

import { Merchant } from '@prisma/client';
import prisma from '../config/prisma.js';
import { AppError } from '../utils/errors.js';
import { generateApiKeyMaterial, hashApiKey, MAX_ACTIVE_API_KEYS } from '../utils/api-key.utils.js';

export type ApiKeySummary = {
  id: string;
  prefix: string;
  label: string | null;
  lastUsedAt: Date | null;
  createdAt: Date;
};

export type CreateApiKeyResult = ApiKeySummary & {
  key: string;
};

type ApiKeyListRow = {
  id: string;
  prefix: string | null;
  name: string | null;
  lastUsedAt: Date | null;
  createdAt: Date;
};

const toApiKeySummary = (apiKey: ApiKeyListRow): ApiKeySummary => ({
  id: apiKey.id,
  prefix: apiKey.prefix ?? '',
  label: apiKey.name,
  lastUsedAt: apiKey.lastUsedAt,
  createdAt: apiKey.createdAt,
});

const activeApiKeyWhere = (merchantId: string) => ({
  merchantId,
  revokedAt: null,
  OR: [{ expiresAt: null }, { expiresAt: { gt: new Date() } }],
});

export const createApiKey = async (
  merchantId: string,
  label?: string,
): Promise<CreateApiKeyResult> => {
  const { rawKey, prefix, keyHash } = generateApiKeyMaterial();
  const normalizedLabel = label?.trim() || null;

  const apiKey = await prisma.$transaction(async tx => {
    const activeKeys = await tx.apiKey.count({
      where: activeApiKeyWhere(merchantId),
    });

    if (activeKeys >= MAX_ACTIVE_API_KEYS) {
      throw new AppError(400, `Maximum of ${MAX_ACTIVE_API_KEYS} active API keys allowed`);
    }

    return tx.apiKey.create({
      data: {
        merchantId,
        keyHash,
        prefix,
        name: normalizedLabel,
      },
    });
  });

  return {
    ...toApiKeySummary(apiKey),
    key: rawKey,
  };
};

export const listApiKeys = async (merchantId: string): Promise<ApiKeySummary[]> => {
  const apiKeys = await prisma.apiKey.findMany({
    where: {
      merchantId,
      revokedAt: null,
    },
    orderBy: { createdAt: 'desc' },
    select: {
      id: true,
      prefix: true,
      name: true,
      lastUsedAt: true,
      createdAt: true,
    },
  });

  return apiKeys.map(toApiKeySummary);
};

export const revokeApiKey = async (merchantId: string, keyId: string): Promise<void> => {
  const apiKey = await prisma.apiKey.findFirst({
    where: { id: keyId, merchantId },
  });

  if (!apiKey) {
    throw new AppError(404, 'API key not found');
  }

  if (apiKey.revokedAt) {
    throw new AppError(400, 'API key already revoked');
  }

  await prisma.apiKey.update({
    where: { id: keyId },
    data: { revokedAt: new Date() },
  });
};

export const authenticateApiKey = async (rawKey: string): Promise<Merchant | null> => {
  const keyHash = hashApiKey(rawKey);
  const apiKey = await prisma.apiKey.findUnique({
    where: { keyHash },
    include: { merchant: true },
  });

  if (!apiKey || apiKey.revokedAt) {
    return null;
  }

  if (apiKey.expiresAt && apiKey.expiresAt.getTime() < Date.now()) {
    return null;
  }

  await prisma.apiKey.update({
    where: { id: apiKey.id },
    data: { lastUsedAt: new Date() },
  });

  return apiKey.merchant;
};

import crypto from 'node:crypto';
import jwt from 'jsonwebtoken';
import { Keypair } from '@stellar/stellar-sdk';
import prisma from '../config/prisma.js';
import { environment } from '../config/environment.js';

const NONCE_EXPIRY_MS = 5 * 60 * 1000;
const REFRESH_TOKEN_EXPIRY_MS = 7 * 24 * 60 * 60 * 1000;

export function buildChallengeMessage(address: string, nonce: string, createdAt: Date): string {
  return [
    'Shade Authentication',
    `Address: ${address}`,
    `Nonce: ${nonce}`,
    `Timestamp: ${createdAt.toISOString()}`,
  ].join('\n');
}

export async function createNonce(address: string) {
  const nonce = crypto.randomUUID();
  const createdAt = new Date();
  const expiresAt = new Date(createdAt.getTime() + NONCE_EXPIRY_MS);
  const message = buildChallengeMessage(address, nonce, createdAt);

  const authNonce = await prisma.authNonce.create({
    data: { address, nonce, message, expiresAt },
  });

  return { nonce: authNonce.nonce, message: authNonce.message, expiresAt: authNonce.expiresAt };
}

export async function verifySignature(address: string, nonce: string, rawSignature: string) {
  const authNonce = await prisma.authNonce.findUnique({ where: { nonce } });
  if (!authNonce) {
    return { valid: false, reason: 'Nonce not found' } as const;
  }
  if (authNonce.address !== address) {
    return { valid: false, reason: 'Address mismatch' } as const;
  }
  if (authNonce.usedAt) {
    return { valid: false, reason: 'Nonce already used' } as const;
  }
  if (new Date() > authNonce.expiresAt) {
    return { valid: false, reason: 'Nonce expired' } as const;
  }

  const message = buildChallengeMessage(address, authNonce.nonce, authNonce.createdAt);
  const messageBytes = Buffer.from(message, 'utf-8');
  const signatureBytes = Buffer.from(rawSignature, 'hex');

  let isValid: boolean;
  try {
    const keypair = Keypair.fromPublicKey(address);
    isValid = keypair.verify(messageBytes, signatureBytes);
  } catch {
    return { valid: false, reason: 'Invalid address or signature format' } as const;
  }

  if (!isValid) {
    return { valid: false, reason: 'Signature verification failed' } as const;
  }

  await prisma.authNonce.update({
    where: { id: authNonce.id },
    data: { usedAt: new Date() },
  });

  return { valid: true, reason: null } as const;
}

export async function upsertMerchant(address: string) {
  const existing = await prisma.merchant.findFirst({ where: { address } });
  if (existing) {
    return existing;
  }
  const merchantId = crypto.randomInt(100_000, 999_999);
  const merchant = await prisma.merchant.create({
    data: { merchantId, address },
  });
  return merchant;
}

export function issueAccessToken(merchantId: string, address: string): string {
  return jwt.sign({ sub: merchantId, address }, environment.jwtSecret, { expiresIn: '15m' });
}

export async function issueRefreshToken(merchantId: string): Promise<string> {
  const token = crypto.randomUUID();
  const expiresAt = new Date(Date.now() + REFRESH_TOKEN_EXPIRY_MS);

  await prisma.refreshToken.create({
    data: { merchantId, token, expiresAt },
  });

  return token;
}

export async function authenticateWallet(address: string, nonce: string, signature: string) {
  const verification = await verifySignature(address, nonce, signature);
  if (!verification.valid) {
    return { success: false, reason: verification.reason } as const;
  }

  const merchant = await upsertMerchant(address);
  const accessToken = issueAccessToken(merchant.id, merchant.address);
  const refreshToken = await issueRefreshToken(merchant.id);

  return {
    success: true,
    accessToken,
    refreshToken,
    merchant: {
      id: merchant.id,
      address: merchant.address,
      isRegistered: merchant.registered,
    },
  } as const;
}

import nodemailer from 'nodemailer';
import { Resend } from 'resend';
import { environment } from '../config/environment.js';
import type { Invoice, Merchant } from '@prisma/client';
import { generateInvoicePdf } from './invoice-pdf.services.js';

export interface EmailAttachment {
  filename: string;
  content: Buffer;
}

const escapeHtml = (value: string): string =>
  value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');

const buildOtpEmailContent = (firstName: string, code: string) => {
  const safeFirstName = escapeHtml(firstName);
  const subject = 'Verify your Shade email';
  const html = `
    <p>Hi ${safeFirstName},</p>
    <p>Your email verification code is:</p>
    <p><strong style="font-size: 24px; letter-spacing: 4px;">${code}</strong></p>
    <p>This code expires in 10 minutes.</p>
  `.trim();
  const text = `Hi ${firstName},\n\nYour verification code is: ${code}\n\nThis code expires in 10 minutes.`;

  return { subject, html, text };
};

const sendViaResend = async (
  to: string,
  subject: string,
  html: string,
  attachments?: EmailAttachment[],
): Promise<void> => {
  const resend = new Resend(environment.email.resendApiKey);
  const { error } = await resend.emails.send({
    from: environment.email.from,
    to,
    subject,
    html,
    attachments: attachments?.map(({ filename, content }) => ({ filename, content })),
  });

  if (error) {
    throw new Error(`Failed to send email via Resend: ${error.message}`);
  }
};

const sendViaSmtp = async (
  to: string,
  subject: string,
  html: string,
  text: string,
  attachments?: EmailAttachment[],
): Promise<void> => {
  const transporter = nodemailer.createTransport({
    host: environment.email.smtp.host,
    port: environment.email.smtp.port,
    secure: environment.email.smtp.secure,
    auth: {
      user: environment.email.smtp.user,
      pass: environment.email.smtp.pass,
    },
  });

  await transporter.sendMail({
    from: environment.email.from,
    to,
    subject,
    html,
    text,
    attachments,
  });
};

/**
 * Delivers a one-time verification code to the merchant's email address.
 */
export const sendOtp = async (to: string, code: string, firstName: string): Promise<void> => {
  const { subject, html, text } = buildOtpEmailContent(firstName, code);

  switch (environment.email.provider) {
    case 'resend':
      await sendViaResend(to, subject, html);
      return;
    case 'smtp':
      await sendViaSmtp(to, subject, html, text);
      return;
    case 'console':
    default:
      console.log(`[OTP] Verification code ${code} sent to ${to} for ${firstName}`);
  }
};

const buildInvoiceEmailContent = (invoice: Invoice, merchant: Merchant) => {
  const merchantName = escapeHtml(merchant.businessName || 'Your merchant');
  const description = escapeHtml(invoice.description);
  const subject = `Invoice from ${merchant.businessName || 'Shade'}: ${invoice.description}`;
  const html = `
    <p>Hi,</p>
    <p>${merchantName} has sent you an invoice for <strong>${description}</strong>.</p>
    <p>Amount: <strong>${invoice.amount.toString()} ${escapeHtml(invoice.token)}</strong></p>
    <p>Status: <strong>${invoice.status}</strong></p>
    <p>Your invoice is attached as a PDF.</p>
  `.trim();
  const text = `Hi,\n\n${merchant.businessName || 'Your merchant'} has sent you an invoice for ${invoice.description}.\n\nAmount: ${invoice.amount.toString()} ${invoice.token}\nStatus: ${invoice.status}\n\nYour invoice is attached as a PDF.`;

  return { subject, html, text };
};

/**
 * Emails the invoice to `invoice.email` with a freshly generated PDF attached.
 * No-ops (does not throw) when the invoice has no email on file — callers
 * that need to surface that as a user-facing error (e.g. the /send route)
 * should check `invoice.email` before calling this.
 */
export const sendInvoiceEmail = async (invoice: Invoice, merchant: Merchant): Promise<void> => {
  if (!invoice.email) {
    return;
  }

  const pdf = await generateInvoicePdf(invoice, merchant);
  const { subject, html, text } = buildInvoiceEmailContent(invoice, merchant);
  const attachments: EmailAttachment[] = [
    { filename: `invoice-${invoice.paymentSlug}.pdf`, content: pdf },
  ];

  switch (environment.email.provider) {
    case 'resend':
      await sendViaResend(invoice.email, subject, html, attachments);
      return;
    case 'smtp':
      await sendViaSmtp(invoice.email, subject, html, text, attachments);
      return;
    case 'console':
    default:
      console.log(`[Invoice email] Invoice ${invoice.paymentSlug} (${pdf.length} byte PDF) sent`);
  }
};

import type { Invoice, InvoiceStatus as PrismaInvoiceStatus, Prisma } from '@prisma/client';
import prisma from '../config/prisma.js';
import { AppError } from '../utils/errors.js';
import { generatePaymentSlug } from '../utils/slug.js';
import {
  CreateInvoiceInput,
  InvoiceListFilters,
  InvoicePagination,
  parseAmount,
} from '../utils/invoice.validation.js';

const SLUG_MAX_RETRIES = 5;

// String constants matching the Prisma `Status` enum. Defined locally so this
// module never imports a runtime value from `@prisma/client` (the generated
// client is mocked in tests and not generated in CI).
const InvoiceStatus = {
  DRAFT: 'DRAFT',
  PENDING: 'PENDING',
  PAID: 'PAID',
  CANCELLED: 'CANCELLED',
} as const satisfies Record<string, PrismaInvoiceStatus>;

/**
 * Public-facing view of an invoice. `amount` is serialized to a string because
 * `BigInt` is not JSON-serializable.
 */
export const sanitizeInvoice = (invoice: Invoice) => ({
  id: invoice.id,
  paymentSlug: invoice.paymentSlug,
  description: invoice.description,
  amount: invoice.amount.toString(),
  token: invoice.token,
  status: invoice.status,
  merchantId: invoice.merchantId,
  email: invoice.email,
  expiresAt: invoice.expiresAt,
  datePaid: invoice.datePaid,
  createdAt: invoice.createdAt,
  updatedAt: invoice.updatedAt,
});

const isUniqueSlugError = (error: unknown): boolean => {
  if (typeof error !== 'object' || error === null) return false;
  const { code, meta } = error as { code?: string; meta?: { target?: unknown } };
  return code === 'P2002' && Array.isArray(meta?.target) && meta.target.includes('paymentSlug');
};

export const createInvoice = async (merchantId: string, data: CreateInvoiceInput) => {
  const amount = parseAmount(data.amount);
  if (amount === null) {
    throw new AppError(400, 'amount must be a positive integer');
  }

  const status: PrismaInvoiceStatus = data.isDraft ? InvoiceStatus.DRAFT : InvoiceStatus.PENDING;
  const expiresAt = data.expiresAt ? new Date(data.expiresAt) : null;

  for (let attempt = 0; attempt < SLUG_MAX_RETRIES; attempt++) {
    try {
      const invoice = await prisma.invoice.create({
        data: {
          merchantId,
          description: data.description.trim(),
          amount,
          token: data.token.trim(),
          email: data.payerEmail?.trim() ?? null,
          expiresAt,
          status,
          paymentSlug: generatePaymentSlug(),
        },
      });
      return sanitizeInvoice(invoice);
    } catch (error) {
      if (isUniqueSlugError(error) && attempt < SLUG_MAX_RETRIES - 1) {
        continue;
      }
      throw error;
    }
  }

  throw new AppError(500, 'Failed to generate a unique payment slug');
};

export const listInvoices = async (
  merchantId: string,
  filters: InvoiceListFilters,
  pagination: InvoicePagination,
) => {
  const where: Prisma.InvoiceWhereInput = { merchantId };

  if (filters.status) {
    where.status = filters.status;
  }

  if (filters.token) {
    where.token = filters.token;
  }

  if (filters.startDate || filters.endDate) {
    where.createdAt = {};
    if (filters.startDate) where.createdAt.gte = filters.startDate;
    if (filters.endDate) where.createdAt.lte = filters.endDate;
  }

  const [invoices, total] = await Promise.all([
    prisma.invoice.findMany({
      where,
      take: pagination.limit,
      skip: pagination.offset,
      orderBy: { createdAt: 'desc' },
    }),
    prisma.invoice.count({ where }),
  ]);

  return {
    data: invoices.map(sanitizeInvoice),
    pagination: {
      limit: pagination.limit,
      offset: pagination.offset,
      total,
    },
  };
};

export const getInvoice = async (merchantId: string, id: string) => {
  const invoice = await prisma.invoice.findFirst({
    where: { id, merchantId },
  });

  if (!invoice) {
    throw new AppError(404, 'Invoice not found');
  }

  return sanitizeInvoice(invoice);
};

/**
 * Fetches the raw invoice + merchant records, scoped to the owning merchant,
 * for the PDF/email flows that need fields beyond the sanitized public view
 * (payer address, fiat breakdown, merchant logo).
 */
export const getInvoiceWithMerchant = async (merchantId: string, id: string) => {
  const invoice = await prisma.invoice.findFirst({
    where: { id, merchantId },
    include: { merchant: true },
  });

  if (!invoice) {
    throw new AppError(404, 'Invoice not found');
  }

  return invoice;
};

export const voidInvoice = async (merchantId: string, id: string) => {
  const invoice = await prisma.invoice.findFirst({
    where: { id, merchantId },
  });

  if (!invoice) {
    throw new AppError(404, 'Invoice not found');
  }

  if (invoice.status !== InvoiceStatus.PENDING) {
    throw new AppError(400, 'Only pending invoices can be voided');
  }

  const updated = await prisma.invoice.update({
    where: { id: invoice.id },
    data: { status: InvoiceStatus.CANCELLED },
  });

  return sanitizeInvoice(updated);
};

import { Merchant, Prisma } from '@prisma/client';
import prisma from '../config/prisma.js';
import { AppError } from '../utils/errors.js';
import { RegisterMerchantInput, UpdateMerchantInput } from '../utils/validation.js';
import { generateOtp, hashOtp } from './otp.services.js';
import { sendOtp } from './email.service.js';
import { Keypair } from '@stellar/stellar-sdk';

const OTP_EXPIRY_MS = 10 * 60 * 1000;

interface MerchantData {
  merchantId: number;
  email?: string;
  address: string;
  active?: boolean;
  verified?: boolean;
}

/**
 * Returns a public-facing view of a merchant. Built as an allow-list so that
 * any sensitive fields added to the model later are never exposed by default.
 */
export const sanitizeMerchant = (merchant: Merchant) => ({
  id: merchant.id,
  merchantId: merchant.merchantId,
  email: merchant.email,
  address: merchant.address,
  account: merchant.account,
  merchantKey: merchant.merchantKey,
  firstName: merchant.firstName,
  lastName: merchant.lastName,
  businessName: merchant.businessName,
  category: merchant.category,
  description: merchant.description,
  logo: merchant.logo,
  webhook: merchant.webhook,
  active: merchant.active,
  verified: merchant.verified,
  emailVerified: merchant.emailVerified,
  registered: merchant.registered,
  createdAt: merchant.createdAt,
  updatedAt: merchant.updatedAt,
});

export const createMerchant = async (merchantData: MerchantData) => {
  try {
    const merchant = await prisma.merchant.create({
      data: merchantData,
    });
    return merchant;
  } catch (error) {
    throw error;
  }
};

export const getMerchant = async (merchantId: number) => {
  try {
    const merchant = await prisma.merchant.findUnique({
      where: {
        merchantId: merchantId,
      },
    });
    return merchant;
  } catch (error) {
    throw error;
  }
};

export const listMerchants = async (limit: number, offset: number) => {
  try {
    const merchants = await prisma.merchant.findMany({
      take: limit,
      skip: offset,
    });
    return merchants;
  } catch (error) {
    throw error;
  }
};

/**
 * Completes a merchant's profile after wallet authentication.
 *
 * Enforces that the email is unique across merchants and that the profile has
 * not already been completed, persists the profile data, resets email
 * verification, and triggers an OTP email.
 */
export const registerMerchant = async (merchantId: string, data: RegisterMerchantInput) => {
  const merchant = await prisma.merchant.findUnique({
    where: { id: merchantId },
  });

  if (!merchant) {
    throw new AppError(404, 'Merchant not found');
  }

  if (merchant.registered) {
    throw new AppError(409, 'Profile already set up');
  }

  const normalizedEmail = data.email.trim().toLowerCase();

  const existingEmail = await prisma.merchant.findFirst({
    where: {
      email: normalizedEmail,
      NOT: { id: merchantId },
    },
  });

  if (existingEmail) {
    throw new AppError(409, 'Email already registered');
  }

  const code = generateOtp();
  const emailOtp = await hashOtp(code);
  const emailOtpExpiresAt = new Date(Date.now() + OTP_EXPIRY_MS);

  const updatedMerchant = await prisma.merchant.update({
    where: { id: merchantId },
    data: {
      firstName: data.firstName.trim(),
      lastName: data.lastName.trim(),
      email: normalizedEmail,
      businessName: data.businessName.trim(),
      category: data.category.trim(),
      description: data.description.trim(),
      logo: data.logo?.trim() ?? null,
      emailVerified: false,
      registered: true,
      emailOtp,
      emailOtpExpiresAt,
    },
  });

  try {
    await sendOtp(normalizedEmail, code, data.firstName.trim());
  } catch (err) {
    console.error('Failed to send OTP email after registration', err);
  }

  return sanitizeMerchant(updatedMerchant);
};

/**
 * Returns the authenticated merchant's own profile.
 */
export const getMyProfile = async (id: string) => {
  const merchant = await prisma.merchant.findUnique({ where: { id } });

  if (!merchant) {
    throw new AppError(404, 'Merchant not found');
  }

  return sanitizeMerchant(merchant);
};

/**
 * Generates a fresh Ed25519 signing keypair for the merchant.
 *
 * Persists ONLY the hex-encoded 32-byte public key to `Merchant.merchantKey`,
 * overwriting any previous value (unconditional generate-and-replace). Returns
 * both halves; the hex-encoded 32-byte private key is returned exactly once and
 * is never written to the database or logged.
 *
 * Uploading the public key on-chain (`set_merchant_key`) and signing invoices
 * with the private key are done client/SDK-side and are out of scope here.
 */
export const generateMerchantSigningKey = async (id: string) => {
  const merchant = await prisma.merchant.findUnique({ where: { id } });

  if (!merchant) {
    throw new AppError(404, 'Merchant not found');
  }

  const keypair = Keypair.random();
  const publicKey = Buffer.from(keypair.rawPublicKey()).toString('hex');
  const privateKey = Buffer.from(keypair.rawSecretKey()).toString('hex');

  // Optimistic concurrency: only replace the key we just read. If a concurrent
  // rotation already changed it, no row matches and we reject rather than return
  // a private key whose public half is no longer the one persisted.
  const { count } = await prisma.merchant.updateMany({
    where: { id, merchantKey: merchant.merchantKey },
    data: { merchantKey: publicKey },
  });

  if (count !== 1) {
    throw new AppError(409, 'Signing key was changed concurrently; please retry');
  }

  // Audit only — never include the private key here.
  console.info(
    `[merchant] signing key ${merchant.merchantKey ? 'rotated' : 'created'} for merchant ${id}`,
  );

  return { publicKey, privateKey };
};

/**
 * Partially updates the authenticated merchant's editable profile fields.
 *
 * Only fields present in `data` are written. Strings are trimmed; an empty
 * `logo`/`webhook` is normalized to null so the merchant can clear them.
 * Non-editable fields are never read here, so they cannot be changed.
 */
export const updateMyProfile = async (id: string, data: UpdateMerchantInput) => {
  const updateData: Prisma.MerchantUpdateInput = {};

  const textFields = ['firstName', 'lastName', 'businessName', 'category', 'description'] as const;
  for (const field of textFields) {
    const value = data[field];
    if (value !== undefined) {
      updateData[field] = value.trim();
    }
  }

  if (data.logo !== undefined) {
    const logo = typeof data.logo === 'string' ? data.logo.trim() : data.logo;
    updateData.logo = logo ? logo : null;
  }

  if (data.webhook !== undefined) {
    const webhook = typeof data.webhook === 'string' ? data.webhook.trim() : data.webhook;
    updateData.webhook = webhook ? webhook : null;
  }

  const updated = await prisma.merchant.update({ where: { id }, data: updateData });

  return sanitizeMerchant(updated);
};

import { randomInt } from 'node:crypto';
import bcrypt from 'bcrypt';
import prisma from '../config/prisma.js';
import { AppError } from '../utils/errors.js';
import { sendOtp } from './email.service.js';

const OTP_LENGTH = 6;
const OTP_EXPIRY_MS = 10 * 60 * 1000;
const OTP_RESEND_COOLDOWN_MS = 60 * 1000;
const BCRYPT_ROUNDS = 10;

export const generateOtp = (): string => {
  const min = 10 ** (OTP_LENGTH - 1);
  const max = 10 ** OTP_LENGTH - 1;
  return randomInt(min, max + 1).toString();
};

export const hashOtp = async (code: string): Promise<string> => bcrypt.hash(code, BCRYPT_ROUNDS);

export const verifyOtpHash = async (code: string, hash: string): Promise<boolean> =>
  bcrypt.compare(code, hash);

const getLastOtpSentAt = (expiresAt: Date): Date => new Date(expiresAt.getTime() - OTP_EXPIRY_MS);

/**
 * Generates a 6-digit OTP, stores its bcrypt hash with a 10-minute expiry,
 * and sends the code to the merchant's email.
 */
export const issueEmailOtp = async (merchant: {
  id: string;
  email: string;
  firstName: string | null;
}): Promise<void> => {
  const code = generateOtp();
  const emailOtp = await hashOtp(code);
  const emailOtpExpiresAt = new Date(Date.now() + OTP_EXPIRY_MS);

  await prisma.merchant.update({
    where: { id: merchant.id },
    data: { emailOtp, emailOtpExpiresAt },
  });

  await sendOtp(merchant.email, code, merchant.firstName?.trim() || 'there');
};

/**
 * Validates the submitted OTP against the stored hash and marks the email verified.
 */
export const verifyEmailOtp = async (merchantId: string, code: string) => {
  const merchant = await prisma.merchant.findUnique({
    where: { id: merchantId },
  });

  if (!merchant?.emailOtp || !merchant.emailOtpExpiresAt) {
    throw new AppError(400, 'Invalid verification code');
  }

  if (merchant.emailOtpExpiresAt.getTime() < Date.now()) {
    throw new AppError(400, 'Code expired');
  }

  const isValid = await verifyOtpHash(code, merchant.emailOtp);
  if (!isValid) {
    throw new AppError(400, 'Invalid verification code');
  }

  return prisma.merchant.update({
    where: { id: merchantId },
    data: {
      emailVerified: true,
      emailOtp: null,
      emailOtpExpiresAt: null,
    },
  });
};

/**
 * Re-generates and re-sends the email OTP, rate-limited to one request per minute.
 */
export const resendEmailOtp = async (merchantId: string): Promise<void> => {
  const merchant = await prisma.merchant.findUnique({
    where: { id: merchantId },
  });

  if (!merchant) {
    throw new AppError(404, 'Merchant not found');
  }

  if (!merchant.registered || !merchant.email) {
    throw new AppError(400, 'Registration incomplete');
  }

  if (merchant.emailVerified) {
    throw new AppError(400, 'Email already verified');
  }

  if (merchant.emailOtpExpiresAt) {
    const lastSentAt = getLastOtpSentAt(merchant.emailOtpExpiresAt);
    if (Date.now() - lastSentAt.getTime() < OTP_RESEND_COOLDOWN_MS) {
      throw new AppError(429, 'Please wait before requesting a new code');
    }
  }

  await issueEmailOtp({
    id: merchant.id,
    email: merchant.email,
    firstName: merchant.firstName,
  });
};

import prisma from '../config/prisma.js';
import { AppError } from '../utils/errors.js';
import type { InvoiceStatus as PrismaInvoiceStatus } from '@prisma/client';

const InvoiceStatus = {
  DRAFT: 'DRAFT',
  PENDING: 'PENDING',
  PAID: 'PAID',
  CANCELLED: 'CANCELLED',
  REFUNDED: 'REFUNDED',
} as const satisfies Record<string, PrismaInvoiceStatus>;

const assertInvoiceVisible = (invoice: { status: PrismaInvoiceStatus; expiresAt: Date | null }) => {
  if (
    invoice.status === InvoiceStatus.CANCELLED ||
    invoice.status === InvoiceStatus.PAID ||
    invoice.status === InvoiceStatus.REFUNDED
  ) {
    throw new AppError(410, 'Invoice is no longer available');
  }

  if (invoice.expiresAt && invoice.expiresAt < new Date()) {
    throw new AppError(410, 'expired');
  }
};

export const resolveInvoiceBySlug = async (slug: string) => {
  const invoice = await prisma.invoice.findUnique({
    where: { paymentSlug: slug },
    select: {
      paymentSlug: true,
      description: true,
      amount: true,
      token: true,
      status: true,
      expiresAt: true,
      pricingMode: true,
      merchant: {
        select: {
          businessName: true,
        },
      },
    },
  });

  if (!invoice) {
    throw new AppError(404, 'Invoice not found');
  }

  assertInvoiceVisible(invoice);

  return {
    slug: invoice.paymentSlug,
    description: invoice.description,
    amount: invoice.amount.toString(),
    token: invoice.token,
    status: invoice.status,
    merchantName: invoice.merchant.businessName,
    expiresAt: invoice.expiresAt,
    pricingMode: invoice.pricingMode,
  };
};

/**
 * Fetches the full invoice + merchant records for a publicly visible invoice,
 * applying the same 404/410 visibility rules as `resolveInvoiceBySlug`. Used
 * by the public PDF download route, which needs raw fields (payer, dates,
 * fiat breakdown, logo) rather than the trimmed public-facing view.
 */
export const getInvoiceForPdfBySlug = async (slug: string) => {
  const invoice = await prisma.invoice.findUnique({
    where: { paymentSlug: slug },
    include: { merchant: true },
  });

  if (!invoice) {
    throw new AppError(404, 'Invoice not found');
  }

  assertInvoiceVisible(invoice);

  return invoice;
};

export const confirmPayment = async (slug: string, payerAddress: string, txHash?: string) => {
  return await prisma.$transaction(async tx => {
    const invoice = await tx.invoice.findUnique({
      where: { paymentSlug: slug },
    });

    if (!invoice) {
      throw new AppError(404, 'Invoice not found');
    }

    assertInvoiceVisible(invoice);

    const idempotencyKey = `${invoice.id}-${payerAddress}-${txHash || 'none'}`;

    const confirmation = await tx.paymentConfirmation.upsert({
      where: { idempotencyKey },
      update: {},
      create: {
        invoiceId: invoice.id,
        merchantId: invoice.merchantId,
        payerAddress,
        txHash: txHash || null,
        idempotencyKey,
      },
    });

    return confirmation;
  });
};

