  });

  test('DELETE returns 400 when key is already revoked', async () => {
    prismaMock.refreshToken.findUnique.mockResolvedValue({
      id: 'session-1',
      merchantId: merchant.id,
      token: 'valid-session-token',
      expiresAt: new Date(Date.now() + 60 * 60 * 1000),
      createdAt: new Date(),
      merchant,
    } as any);
    prismaMock.apiKey.findFirst.mockResolvedValue({
      ...apiKeyRecord,
      revokedAt: new Date('2026-06-27T11:00:00.000Z'),
    } as any);

    const response = await request(app)
      .delete('/api/v1/merchants/api-keys/key-1')
      .set('Authorization', 'Bearer valid-session-token');

    expect(response.status).toBe(400);
    expect(response.body).toEqual({ error: 'API key already revoked' });
    expect(prismaMock.apiKey.update).not.toHaveBeenCalled();
  });

  test('revoked key cannot authenticate subsequent requests', async () => {
    prismaMock.apiKey.findUnique.mockResolvedValue({
      ...apiKeyRecord,
      revokedAt: new Date('2026-06-27T14:00:00.000Z'),
      merchant,
    } as any);

    const response = await request(app)
      .get('/api/v1/invoices')
      .set('Authorization', `Bearer ${rawApiKey}`);

    expect(response.status).toBe(401);
  });

  test('API key cannot create additional API keys', async () => {
    prismaMock.apiKey.findUnique.mockResolvedValue({
      ...apiKeyRecord,
      merchant,
    } as any);

    const response = await request(app)
      .post('/api/v1/merchants/api-keys')
      .set('Authorization', `Bearer ${rawApiKey}`)
      .send({ label: 'Secondary' });

    expect(response.status).toBe(401);
    expect(prismaMock.apiKey.create).not.toHaveBeenCalled();
    expect(prismaMock.refreshToken.findUnique).not.toHaveBeenCalled();
  });
});

import { jest, beforeEach } from '@jest/globals';
import { mockReset } from 'jest-mock-extended';
import request from 'supertest';

const mockVerify = { returns: true };
const mockKeypairError = { throws: false };

jest.unstable_mockModule('@stellar/stellar-sdk', () => ({
  Keypair: {
    fromPublicKey: () => {
      if (mockKeypairError.throws) {
        throw new Error('invalid public key');
      }
      return {
        verify: () => mockVerify.returns,
      };
    },
  },
}));

const { default: prismaMock } = (await import('../../src/config/prisma.js')) as any;
const { default: app } = await import('../../src/app.js');

const address = 'GABCDEF123';
const nonce = 'nonce-123';
const signature = 'deadbeef';
const mockDate = new Date('2026-06-21T12:00:00Z');

describe('Auth Routes', () => {
  beforeEach(() => {
    mockReset(prismaMock);
    jest.useFakeTimers({ now: mockDate });
    mockVerify.returns = true;
    mockKeypairError.throws = false;
  });

  afterEach(() => {
    jest.useRealTimers();
  });

  describe('POST /api/v1/auth/verify', () => {
    const mockAuthNonce = {
      id: 'uuid-1',
      address,
      nonce,
      message: `Shade Authentication\nAddress: ${address}\nNonce: ${nonce}\nTimestamp: 2026-06-21T12:00:00.000Z`,
      expiresAt: new Date('2026-06-21T12:05:00.000Z'),
      usedAt: null,
      createdAt: mockDate,
      merchantId: null,
    };

    test('should return 200 with tokens for a valid signature (new merchant)', async () => {
      prismaMock.authNonce.findUnique.mockResolvedValue(mockAuthNonce);
      prismaMock.merchant.findFirst.mockResolvedValue(null);
      prismaMock.merchant.create.mockResolvedValue({
        id: 'merchant-uuid',
        merchantId: 123456,
        address,
        account: null,
        email: null,
        firstName: null,
        lastName: null,
        businessName: null,
        category: null,
        description: null,
        logo: null,
        webhook: null,
        active: true,
        verified: false,
        emailVerified: false,
        registered: false,
        createdAt: mockDate,
        updatedAt: mockDate,
      });
      prismaMock.refreshToken.create.mockResolvedValue({
        id: 'session-uuid',
        merchantId: 'merchant-uuid',
        token: 'refresh-uuid',
        expiresAt: new Date('2026-06-28T12:00:00.000Z'),
        createdAt: mockDate,
      });
      prismaMock.authNonce.update.mockResolvedValue(mockAuthNonce);

      const response = await request(app)
        .post('/api/v1/auth/verify')
        .send({ address, nonce, signature });

      expect(response.status).toBe(200);
      expect(response.body).toMatchObject({
        accessToken: expect.any(String),
        refreshToken: expect.any(String),
        merchant: {
          id: 'merchant-uuid',
          address,
          isRegistered: false,
        },
      });
    });

    test('should return 200 with isRegistered: true for an existing merchant with firstName', async () => {
      prismaMock.authNonce.findUnique.mockResolvedValue(mockAuthNonce);
      prismaMock.merchant.findFirst.mockResolvedValue({
        id: 'merchant-uuid',
        merchantId: 123456,
        address,
        account: null,
        email: 'test@merchant.com',
        firstName: 'Jane',
        lastName: 'Doe',
        businessName: 'Acme',
        category: 'retail',
        description: null,
        logo: null,
        webhook: null,
        active: true,
        verified: true,
        emailVerified: true,
        registered: true,
        createdAt: mockDate,
        updatedAt: mockDate,
      });
      prismaMock.refreshToken.create.mockResolvedValue({
        id: 'session-uuid',
        merchantId: 'merchant-uuid',
        token: 'refresh-uuid',
        expiresAt: new Date('2026-06-28T12:00:00.000Z'),
        createdAt: mockDate,
      });
      prismaMock.authNonce.update.mockResolvedValue(mockAuthNonce);

      const response = await request(app)
        .post('/api/v1/auth/verify')
        .send({ address, nonce, signature });

      expect(response.status).toBe(200);
      expect(response.body.merchant).toMatchObject({
        isRegistered: true,
      });
    });

    test('should return 401 for an invalid signature', async () => {
      mockVerify.returns = false;
      prismaMock.authNonce.findUnique.mockResolvedValue(mockAuthNonce);

      const response = await request(app)
        .post('/api/v1/auth/verify')
        .send({ address, nonce, signature });

      expect(response.status).toBe(401);
      expect(response.body).toMatchObject({ error: 'Signature verification failed' });
    });

    test('should return 401 for an expired nonce', async () => {
      jest.setSystemTime(new Date('2026-06-21T12:10:00.000Z'));
      prismaMock.authNonce.findUnique.mockResolvedValue(mockAuthNonce);

      const response = await request(app)
        .post('/api/v1/auth/verify')
        .send({ address, nonce, signature });

      expect(response.status).toBe(401);
      expect(response.body).toMatchObject({ error: 'Nonce expired' });
    });

    test('should return 401 for a replayed (already used) nonce', async () => {
      prismaMock.authNonce.findUnique.mockResolvedValue({
        ...mockAuthNonce,
        usedAt: new Date('2026-06-21T12:01:00.000Z'),
      });

      const response = await request(app)
        .post('/api/v1/auth/verify')
        .send({ address, nonce, signature });

      expect(response.status).toBe(401);
      expect(response.body).toMatchObject({ error: 'Nonce already used' });
    });

    test('should return 400 when required fields are missing', async () => {
      const response = await request(app).post('/api/v1/auth/verify').send({});

      expect(response.status).toBe(400);
    });

    test('should return 400 when fields are not strings', async () => {
      const response = await request(app)
        .post('/api/v1/auth/verify')
        .send({ address: 123, nonce: true, signature: [] });

      expect(response.status).toBe(400);
    });

    test('should return 401 when nonce is not found', async () => {
      prismaMock.authNonce.findUnique.mockResolvedValue(null);

      const response = await request(app)
        .post('/api/v1/auth/verify')
        .send({ address, nonce, signature });

      expect(response.status).toBe(401);
      expect(response.body).toMatchObject({ error: 'Nonce not found' });
    });

    test('should return 401 when signing address does not match the nonce address', async () => {
      prismaMock.authNonce.findUnique.mockResolvedValue(mockAuthNonce);

      const response = await request(app)
        .post('/api/v1/auth/verify')
        .send({ address: 'GWRONG', nonce, signature });

      expect(response.status).toBe(401);
      expect(response.body).toMatchObject({ error: 'Address mismatch' });
    });
  });
});

import { jest } from '@jest/globals';
import { mockReset } from 'jest-mock-extended';
import jwt from 'jsonwebtoken';
import request from 'supertest';

const sendInvoiceEmailMock = jest.fn(async () => undefined);

jest.unstable_mockModule('../../src/services/email.service.js', () => ({
  __esModule: true,
  sendOtp: jest.fn(async () => undefined),
  sendInvoiceEmail: sendInvoiceEmailMock,
}));

const { default: prismaMock } = (await import('../../src/config/prisma.js')) as any;
const { environment } = await import('../../src/config/environment.js');
const { default: app } = await import('../../src/app.js');

const MERCHANT_ID = 'merchant-1';

const merchant = {
  id: MERCHANT_ID,
  merchantId: 1,
  address: '0x123',
  account: null,
  email: 'merchant@example.com',
  firstName: null,
  lastName: null,
  businessName: null,
  category: null,
  description: null,
  logo: null,
  webhook: null,
  active: true,
  verified: false,
  emailVerified: false,
  registered: true,
  createdAt: new Date(),
  updatedAt: new Date(),
};

const baseInvoice = {
  id: 'invoice-1',
  invoiceId: null,
  paymentSlug: 'aZ09-_slug',
  description: 'Website design',
  amount: 5000n,
  token: 'USDC',
  merchantId: MERCHANT_ID,
  status: 'PENDING',
  ref: null,
  payer: null,
  payerEmail: null,
  email: null,
  expiresAt: null,
  datePaid: null,
  createdAt: new Date('2026-01-01T00:00:00.000Z'),
  updatedAt: new Date('2026-01-01T00:00:00.000Z'),
};

const authenticate = () => {
  prismaMock.merchant.findUnique.mockResolvedValue(merchant as any);
};

const accessToken = jwt.sign(
  { sub: MERCHANT_ID, address: merchant.address },
  environment.jwtSecret,
);
const auth = { Authorization: `Bearer ${accessToken}` };

describe('Invoice routes', () => {
  beforeEach(() => {
    mockReset(prismaMock);
    sendInvoiceEmailMock.mockClear();
  });

  describe('POST /api/v1/invoices', () => {
    test('returns 401 when unauthenticated', async () => {
      const response = await request(app)
        .post('/api/v1/invoices')
        .send({ description: 'x', amount: '100', token: 'USDC' });

      expect(response.status).toBe(401);
      expect(prismaMock.invoice.create).not.toHaveBeenCalled();
    });

    test('returns 201 with a unique url-safe paymentSlug', async () => {
      authenticate();
      prismaMock.invoice.create.mockImplementation(async (args: any) => ({
        ...baseInvoice,
        ...args.data,
      }));

      const response = await request(app)
        .post('/api/v1/invoices')
        .set(auth)
        .send({ description: 'Website design', amount: '5000', token: 'USDC' });

      expect(response.status).toBe(201);
      expect(response.body.status).toBe('PENDING');
      expect(response.body.amount).toBe('5000');
      expect(response.body.paymentSlug).toMatch(/^[A-Za-z0-9_-]+$/);
    });

    test('creates a DRAFT invoice when isDraft is true', async () => {
      authenticate();
      prismaMock.invoice.create.mockImplementation(async (args: any) => ({
        ...baseInvoice,
        ...args.data,
      }));

      const response = await request(app)
        .post('/api/v1/invoices')
        .set(auth)
        .send({ description: 'Draft', amount: '5000', token: 'USDC', isDraft: true });

      expect(response.status).toBe(201);
      expect(response.body.status).toBe('DRAFT');
    });

    test('returns 400 when amount is not positive or token is empty', async () => {
      authenticate();

      const response = await request(app)
        .post('/api/v1/invoices')
        .set(auth)
        .send({ description: 'x', amount: -5, token: '' });

      expect(response.status).toBe(400);
      expect(response.body.errors).toMatchObject({
        amount: expect.any(String),
        token: expect.any(String),
      });
      expect(prismaMock.invoice.create).not.toHaveBeenCalled();
    });
  });

  describe('GET /api/v1/invoices', () => {
    test('returns a paginated list scoped to the merchant with status filter', async () => {
      authenticate();
      prismaMock.invoice.findMany.mockResolvedValue([baseInvoice] as any);
      prismaMock.invoice.count.mockResolvedValue(1 as any);

      const response = await request(app)
        .get('/api/v1/invoices?status=PENDING&limit=10&offset=0')
        .set(auth);

      expect(response.status).toBe(200);
      expect(response.body.data).toHaveLength(1);
      expect(response.body.pagination).toEqual({ limit: 10, offset: 0, total: 1 });

      const findArgs = prismaMock.invoice.findMany.mock.calls[0][0];
      expect(findArgs.where).toMatchObject({ merchantId: MERCHANT_ID, status: 'PENDING' });
    });

    test('clamps limit to the maximum of 100', async () => {
      authenticate();
      prismaMock.invoice.findMany.mockResolvedValue([] as any);
      prismaMock.invoice.count.mockResolvedValue(0 as any);

      const response = await request(app).get('/api/v1/invoices?limit=500').set(auth);

      expect(response.status).toBe(200);
      expect(response.body.pagination.limit).toBe(100);
    });
  });

  describe('GET /api/v1/invoices/:id', () => {
    test('returns 200 when the invoice belongs to the merchant', async () => {
      authenticate();
      prismaMock.invoice.findFirst.mockResolvedValue(baseInvoice as any);

      const response = await request(app).get('/api/v1/invoices/invoice-1').set(auth);

      expect(response.status).toBe(200);
      expect(response.body.id).toBe('invoice-1');
    });

    test('returns 404 when the invoice is missing or owned by another merchant', async () => {
      authenticate();
      prismaMock.invoice.findFirst.mockResolvedValue(null);

      const response = await request(app).get('/api/v1/invoices/other').set(auth);

      expect(response.status).toBe(404);
    });
  });

  describe('PATCH /api/v1/invoices/:id/void', () => {
    test('voids a PENDING invoice', async () => {
      authenticate();
      prismaMock.invoice.findFirst.mockResolvedValue(baseInvoice as any);
      prismaMock.invoice.update.mockResolvedValue({
        ...baseInvoice,
        status: 'CANCELLED',
      } as any);

      const response = await request(app).patch('/api/v1/invoices/invoice-1/void').set(auth);

      expect(response.status).toBe(200);
      expect(response.body.status).toBe('CANCELLED');
    });

    test('returns 400 when voiding a non-PENDING invoice', async () => {
      authenticate();
      prismaMock.invoice.findFirst.mockResolvedValue({
        ...baseInvoice,
        status: 'PAID',
      } as any);

      const response = await request(app).patch('/api/v1/invoices/invoice-1/void').set(auth);

      expect(response.status).toBe(400);
      expect(prismaMock.invoice.update).not.toHaveBeenCalled();
    });
  });

  describe('GET /api/v1/invoices/:id/pdf', () => {
    test('returns 401 when unauthenticated', async () => {
      const response = await request(app).get('/api/v1/invoices/invoice-1/pdf');

      expect(response.status).toBe(401);
    });

    test('returns 404 when the invoice is missing or owned by another merchant', async () => {
      authenticate();
      prismaMock.invoice.findFirst.mockResolvedValue(null);

      const response = await request(app).get('/api/v1/invoices/other/pdf').set(auth);

      expect(response.status).toBe(404);
    });

    test('streams a real PDF scoped to the authenticated merchant, never touching disk', async () => {
      authenticate();
      prismaMock.invoice.findFirst.mockResolvedValue({ ...baseInvoice, merchant } as any);

      const response = await request(app).get('/api/v1/invoices/invoice-1/pdf').set(auth);

      expect(response.status).toBe(200);
      expect(response.headers['content-type']).toContain('application/pdf');
      expect(response.headers['content-disposition']).toBe(
        `attachment; filename="invoice-${baseInvoice.paymentSlug}.pdf"`,
      );
      const body = response.body as Buffer;
      expect(Buffer.isBuffer(body)).toBe(true);
      expect(body.subarray(0, 5).toString('ascii')).toBe('%PDF-');

      const findArgs = prismaMock.invoice.findFirst.mock.calls[0][0];
      expect(findArgs.where).toMatchObject({ id: 'invoice-1', merchantId: MERCHANT_ID });
    });
  });

  describe('POST /api/v1/invoices/:id/send', () => {
    test('returns 401 when unauthenticated', async () => {
      const response = await request(app).post('/api/v1/invoices/invoice-1/send');

      expect(response.status).toBe(401);
      expect(sendInvoiceEmailMock).not.toHaveBeenCalled();
    });

    test('returns 404 when the invoice is missing or owned by another merchant', async () => {
      authenticate();
      prismaMock.invoice.findFirst.mockResolvedValue(null);

      const response = await request(app).post('/api/v1/invoices/other/send').set(auth);

      expect(response.status).toBe(404);
      expect(sendInvoiceEmailMock).not.toHaveBeenCalled();
    });

    test('returns 400 and does not attempt to send when the invoice has no email set', async () => {
      authenticate();
      prismaMock.invoice.findFirst.mockResolvedValue({
        ...baseInvoice,
        email: null,
        merchant,
      } as any);

      const response = await request(app).post('/api/v1/invoices/invoice-1/send').set(auth);

      expect(response.status).toBe(400);
      expect(sendInvoiceEmailMock).not.toHaveBeenCalled();
    });

    test('sends the invoice email when invoice.email is set', async () => {
      authenticate();
      const invoiceWithEmail = { ...baseInvoice, email: 'payer@example.com', merchant };
      prismaMock.invoice.findFirst.mockResolvedValue(invoiceWithEmail as any);

      const response = await request(app).post('/api/v1/invoices/invoice-1/send').set(auth);

      expect(response.status).toBe(200);
      expect(sendInvoiceEmailMock).toHaveBeenCalledWith(invoiceWithEmail, merchant);
    });
  });
});

import { jest } from '@jest/globals';
import { mockReset } from 'jest-mock-extended';
import request from 'supertest';

const { default: prismaMock } = (await import('../../src/config/prisma.js')) as any;
const { default: app } = await import('../../src/app.js');

const ME_URL = '/api/v1/merchants/me';

const baseMerchant = {
  id: 'uuid-1',
  merchantId: 1,
  address: '0x123',
  account: 'CCONTRACT',
  email: 'ada@example.com',
  firstName: 'Ada',
  lastName: 'Lovelace',
  businessName: 'Analytical Engines',
  category: 'software',
  description: 'We build computing machines.',
  logo: null,
  webhook: null,
  active: true,
  verified: false,
  emailVerified: false,
  registered: true,
  createdAt: new Date().toISOString(),
  updatedAt: new Date().toISOString(),
  // Internal relations that the sanitizer allow-list must strip from responses.
  refreshTokens: [{ id: 'rt-1', token: 'secret-token' }],
  apiKeys: [{ id: 'ak-1', keyHash: 'hashed-secret' }],
};

const authenticateAs = (merchant: Record<string, unknown>) => {
  prismaMock.refreshToken.findUnique.mockResolvedValue({
    id: 'session-1',
    merchantId: merchant.id,
    token: 'valid-token',
    expiresAt: new Date(Date.now() + 60 * 60 * 1000),
    createdAt: new Date(),
    merchant,
  } as any);
};

describe('GET /api/v1/merchants/me', () => {
  beforeEach(() => mockReset(prismaMock));

  test('returns 401 when unauthenticated', async () => {
    const response = await request(app).get(ME_URL);
    expect(response.status).toBe(401);
  });

  test('returns 200 with the full profile and no internal fields', async () => {
    authenticateAs(baseMerchant);
    prismaMock.merchant.findUnique.mockResolvedValue(baseMerchant as any);

    const response = await request(app).get(ME_URL).set('Authorization', 'Bearer valid-token');

    expect(response.status).toBe(200);
    expect(response.body).toMatchObject({ id: 'uuid-1', account: 'CCONTRACT', webhook: null });
    expect(response.body).not.toHaveProperty('refreshTokens');
    expect(response.body).not.toHaveProperty('apiKeys');
  });
});

describe('PATCH /api/v1/merchants/me', () => {
  beforeEach(() => mockReset(prismaMock));

  test('returns 401 when unauthenticated', async () => {
    const response = await request(app).patch(ME_URL).send({ firstName: 'Grace' });
    expect(response.status).toBe(401);
    expect(prismaMock.merchant.update).not.toHaveBeenCalled();
  });

  test('updates a valid partial payload and returns 200', async () => {
    authenticateAs(baseMerchant);
    prismaMock.merchant.update.mockImplementation(async (args: any) => ({
      ...baseMerchant,
      ...args.data,
    }));

    const response = await request(app)
      .patch(ME_URL)
      .set('Authorization', 'Bearer valid-token')
      .send({ firstName: 'Grace', webhook: 'https://example.com/hook' });

    expect(response.status).toBe(200);
    expect(response.body).toMatchObject({
      firstName: 'Grace',
      webhook: 'https://example.com/hook',
    });
  });

  test('silently ignores non-editable fields (address/email/merchantId/account)', async () => {
    authenticateAs(baseMerchant);
    prismaMock.merchant.update.mockImplementation(async (args: any) => ({
      ...baseMerchant,
      ...args.data,
    }));

    const response = await request(app)
      .patch(ME_URL)
      .set('Authorization', 'Bearer valid-token')
      .send({
        firstName: 'Grace',
        address: '0xHACK',
        email: 'evil@example.com',
        merchantId: 999,
        account: '0xHACKED',
      });

    expect(response.status).toBe(200);
    const updateArg = prismaMock.merchant.update.mock.calls[0][0];
    expect(updateArg.data).toEqual({ firstName: 'Grace' });
    expect(response.body.address).toBe('0x123');
    expect(response.body.email).toBe('ada@example.com');
    expect(response.body.merchantId).toBe(1);
    expect(response.body.account).toBe('CCONTRACT');
  });

  test('returns 400 for an invalid (non-HTTPS) webhook', async () => {
    authenticateAs(baseMerchant);

    const response = await request(app)
      .patch(ME_URL)
      .set('Authorization', 'Bearer valid-token')
      .send({ webhook: 'http://example.com/hook' });

    expect(response.status).toBe(400);
    expect(response.body.error).toBe('Validation failed');
    expect(prismaMock.merchant.update).not.toHaveBeenCalled();
  });

  test('clears the webhook when sent null', async () => {
    authenticateAs(baseMerchant);
    prismaMock.merchant.update.mockImplementation(async (args: any) => ({
      ...baseMerchant,
      ...args.data,
    }));

    const response = await request(app)
      .patch(ME_URL)
      .set('Authorization', 'Bearer valid-token')
      .send({ webhook: null });

    expect(response.status).toBe(200);
    expect(response.body.webhook).toBeNull();
  });

  test('returns 400 for a required text field sent empty', async () => {
    authenticateAs(baseMerchant);

    const response = await request(app)
      .patch(ME_URL)
      .set('Authorization', 'Bearer valid-token')
      .send({ firstName: '' });

    expect(response.status).toBe(400);
    expect(prismaMock.merchant.update).not.toHaveBeenCalled();
  });

  test('returns 400 for an empty payload', async () => {
    authenticateAs(baseMerchant);

    const response = await request(app)
      .patch(ME_URL)
      .set('Authorization', 'Bearer valid-token')
      .send({});

    expect(response.status).toBe(400);
    expect(prismaMock.merchant.update).not.toHaveBeenCalled();
  });
});

